      'ach_107': '''Cincuenta ASA IV. Hielo en las venas; sevo en el circuito.''',
      'ach_108': '''ASA V. Ave María, llena de presores.''',
      'ach_109': '''Tres ASA vs. En parte anestesista, en parte optimista y en parte nigromante.''',
